import{_ as d,o as t,c,a3 as o}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Bazel API","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Bazel API | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/reference/bazel-api"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/reference/bazel-api"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/bazel-api"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/bazel-api"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/reference/bazel-api"}]]},"headers":[],"relativePath":"zh/xclang/reference/bazel-api.md","filePath":"zh/xclang/reference/bazel-api.md","lastUpdated":1794509097000}'),a={name:"zh/xclang/reference/bazel-api.md"};function l(r,e,n,i,s,b){return t(),c("div",null,[...e[0]||(e[0]=[o('<h1 id="bazel-api" tabindex="-1">Bazel API <a class="header-anchor" href="#bazel-api" aria-label="Permalink to &quot;Bazel API&quot;">​</a></h1><p>本页列出 <code>xclang</code> Bazel 模块提供的所有内容。具体用法见 <a href="./../integrations/bazel">Bazel</a>。模块要求 Bazel 9 与 rules_cc 0.2.25 及以上，位于代码仓库的 <code>packages/bazel</code> 下，每次发版都会发布到 <a href="https://bazel.clice.io" target="_blank" rel="noreferrer">bazel.clice.io</a>。</p><h2 id="工具链" tabindex="-1">工具链 <a class="header-anchor" href="#工具链" aria-label="Permalink to &quot;工具链&quot;">​</a></h2><p>模块会为每个主机注册面向各目标平台的 C++ 工具链：面向主机自身的是 <code>@xclang//bazel/toolchains:&lt;host&gt;</code>，面向其他目标平台的是 <code>&lt;host&gt;-to-&lt;target&gt;</code>；musl 目标平台为 <code>@xclang//bazel/toolchains/musl:&lt;host&gt;-to-&lt;target&gt;</code>，MSVC 目标平台为 <code>@xclang//bazel/toolchains/msvc:&lt;host&gt;-to-&lt;target&gt;</code>（这两组会排在前面优先注册）。每个工具链都使用针对对应目标平台配置的主机压缩包，且只会下载运行 Bazel 所在机器的主机压缩包。MSVC 目标平台以及在非 macOS 主机上构建的 macOS 目标平台会基于根模块获取的厂商 SDK 构建（<a href="#tags">标签</a>）；未配置对应标签时，工具链会使构建报错失败并说明原因。</p><p>每个工具链都会：</p><ul><li>将 Windows 可执行文件命名为 <code>.exe</code>，将共享库命名为 <code>.dll</code>；</li><li>默认将库静态链接进测试与可执行程序中（<a href="./../design/bazel-module#static-by-default">默认静态链接</a>）；</li><li>将外部仓库的头文件作为系统头文件编译（<code>-isystem</code>）；</li><li>抹除 <code>__DATE__</code>、<code>__TIME__</code> 与 <code>__TIMESTAMP__</code> 的时间戳；</li><li>不在命令行中放入任何绝对路径（<a href="./../design/bazel-module#no-absolute-paths">无绝对路径</a>）。</li></ul><h2 id="平台" tabindex="-1">平台 <a class="header-anchor" href="#平台" aria-label="Permalink to &quot;平台&quot;">​</a></h2><p>供 <code>--platforms</code> 使用的 <code>@xclang//platforms:&lt;target&gt;</code>：</p><table tabindex="0"><thead><tr><th>平台</th><th>别名</th><th>目标平台</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td><code>x86_64-linux-gnu</code></td><td>Linux x64，glibc 2.17</td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td><code>aarch64-linux-gnu</code></td><td>Linux arm64，glibc 2.17</td></tr><tr><td><code>x86_64-w64-mingw32</code></td><td><code>x86_64-w64-windows-gnu</code></td><td>Windows x64，MinGW-w64（UCRT）</td></tr><tr><td><code>aarch64-w64-mingw32</code></td><td><code>aarch64-w64-windows-gnu</code></td><td>Windows arm64，MinGW-w64（UCRT）</td></tr><tr><td><code>aarch64-apple-darwin</code></td><td><code>arm64-apple-darwin</code></td><td>macOS arm64；在非 macOS 主机上需配合 Apple 的 SDK</td></tr><tr><td><code>x86_64-apple-darwin</code></td><td></td><td>macOS x64；在非 macOS 主机上需配合 Apple 的 SDK</td></tr><tr><td><code>x86_64-pc-windows-msvc</code></td><td></td><td>Windows x64，MSVC ABI，需配合微软的 SDK</td></tr><tr><td><code>aarch64-pc-windows-msvc</code></td><td></td><td>Windows arm64，MSVC ABI，需配合微软的 SDK</td></tr><tr><td><code>x86_64-unknown-linux-musl</code></td><td><code>x86_64-linux-musl</code></td><td>Linux x64，musl，静态链接</td></tr><tr><td><code>aarch64-unknown-linux-musl</code></td><td><code>aarch64-linux-musl</code></td><td>Linux arm64，musl，静态链接</td></tr></tbody></table><p>每个平台都声明了 <code>@platforms//os</code>、<code>@platforms//cpu</code> 以及 C 标准库约束（<code>@xclang//platforms/libc:glibc</code>、<code>:musl</code>、<code>:mingw</code>、<code>:macosx</code> 或 <code>:msvc</code>）。除额外要求 <code>:musl</code> 或 <code>:msvc</code> 的 musl 与 MSVC 工具链外，其余工具链只要求平台匹配 os 与 cpu；因此用户自定义的只含 os 与 cpu 的平台也可直接使用，若未指定 <code>:musl</code> 或 <code>:msvc</code>，在 Linux 上默认选用 glibc，在 Windows 上默认选用 MinGW。</p><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>默认值</th><th></th></tr></thead><tbody><tr><td><code>asan</code>, <code>tsan</code>, <code>ubsan</code>, <code>lsan</code></td><td>关闭</td><td>作用于整个构建的 sanitizer（如 <code>--features=asan</code>）；<code>asan</code> 会使用 ASan libc++（或带 ASan 插桩的从源码构建的运行时库）编译并链接。Windows 目标平台支持 <code>ubsan</code> 以及 x64 下的 <code>asan</code>（此时每个可执行文件旁都会附带 ASan DLL）；musl 目标平台支持 <code>ubsan</code>。其他不支持的组合会被拒绝</td></tr><tr><td><code>msan</code></td><td>关闭</td><td>作用于整个构建的 MemorySanitizer，需配合从源码构建运行时库（<code>--@xclang//runtimes:source</code>，此时会一并构建 MSan 运行时库）；仅支持 Linux（glibc）目标平台。未启用源码运行时库或面向其他目标平台时会被拒绝</td></tr><tr><td><code>copy_dynamic_libraries_to_binary</code></td><td>Windows 目标平台：开启</td><td>将程序所需的 DLL（包括 ASan 的 DLL）拷贝到 <code>bazel-bin</code> 下可执行文件旁及其 runfiles 目录中，与 Bazel 内置 Windows 工具链的行为一致</td></tr><tr><td><code>cpp_modules</code></td><td>关闭</td><td>C++20 模块：支持 <code>cc_library</code> 与 <code>cc_binary</code> 的 <code>module_interfaces</code>，由 clang-scan-deps 扫描依赖；需配合 <code>--experimental_cpp_modules</code> 使用</td></tr><tr><td><code>gc_sections</code></td><td>Linux 目标平台：在 <code>opt</code> 下开启；Windows 目标平台：关闭</td><td>传入 lld 的 <code>--gc-sections</code>，在 MSVC 目标平台上则传入 lld-link 的 <code>/opt:ref</code>（<a href="./../design/windows#gc-sections-and-static-initializers">为什么在 Windows 上默认关闭</a>）</td></tr><tr><td><code>thinlto_cache</code></td><td>开启</td><td>链接器的 ThinLTO 缓存；仅当 <code>XCLANG_THINLTO_CACHE</code> 指定了目录时才会传入对应参数</td></tr><tr><td><code>generate_dsym_file</code></td><td>关闭</td><td>macOS 目标平台：在链接阶段生成 <code>&lt;name&gt;.dSYM</code>（位于输出组 <code>dsyms</code> 中）；传入 <code>--apple_generate_dsym</code> 可为整个构建开启</td></tr><tr><td><code>supports_dynamic_linker</code></td><td>关闭</td><td>面向 Linux 目标平台启用 Bazel 将依赖库动态链接进测试与可执行文件的行为；关闭时则与其余目标平台一样始终静态链接</td></tr><tr><td><code>release_strip</code></td><td>开启</td><td>控制 <code>&lt;name&gt;.stripped</code> 的剥离方式：对 ELF 与 COFF 使用 <code>--strip-unneeded</code>，对 Mach-O 使用 <code>--strip-all</code>（<a href="./../features/debugging#strip">剥离符号</a>）</td></tr><tr><td><code>modules_embed_all_files</code></td><td>开启</td><td>在 C++20 模块接口生成的模块文件中内嵌源码（<code>-Xclang -fmodules-embed-all-files</code>），使带 <code>-g</code> 编译且 import 它的文件在沙盒内能够读取这些源码</td></tr><tr><td><code>macos_default_link_flags</code></td><td>关闭</td><td>来自 rules_cc 的特性：在 macOS 目标平台的每次链接中传入 <code>-fobjc-link-runtime</code>，将 Foundation 与 libobjc 链接进每个可执行文件和库；关闭时，目标只链接显式声明的 framework（<a href="./../integrations/bazel#build-for-msvc-and-for-macos-anywhere">macOS 链接说明</a>）</td></tr><tr><td><code>no_exported_symbols</code></td><td>macOS 目标平台：在 <code>opt</code> 下开启</td><td>使可执行文件不导出任何符号（<code>-Wl,-no_exported_symbols</code>），避免剥离符号后残留的符号在崩溃日志中误标栈帧名称（<a href="./../features/debugging#strip">剥离符号</a>）；若程序需要加载绑定其自身符号的插件，请关闭此特性</td></tr><tr><td><code>generate_pdb_file</code></td><td>MSVC 目标平台：在 <code>dbg</code> 下开启</td><td>链接时写出 <code>&lt;name&gt;.pdb</code>（位于输出组 <code>pdb_file</code> 中），内部记录相对于执行根目录的路径</td></tr><tr><td><code>dynamic_link_msvcrt</code></td><td>关闭</td><td>MSVC 目标平台：链接 VC 运行时 DLL（<code>/MD</code>），替代默认的混合 CRT</td></tr><tr><td><code>debug_msvcrt</code></td><td>关闭</td><td>MSVC 目标平台：链接调试版 CRT（默认为 <code>/MTd</code>，配合 <code>dynamic_link_msvcrt</code> 时为 <code>/MDd</code>）</td></tr></tbody></table><p>可通过 <code>--features=&lt;name&gt;</code> 为整个构建开启某项特性，通过 <code>--features=-&lt;name&gt;</code> 关闭；也可在单个目标上设置 <code>features = [&quot;&lt;name&gt;&quot;]</code> 或 <code>[&quot;-&lt;name&gt;&quot;]</code>。</p><h2 id="c-标准库" tabindex="-1">C++ 标准库 <a class="header-anchor" href="#c-标准库" aria-label="Permalink to &quot;C++ 标准库&quot;">​</a></h2><p>作用于整个构建的参数：</p><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th><th></th></tr></thead><tbody><tr><td><code>--@xclang//bazel:stdlib</code></td><td><code>libc++</code></td><td>设为 <code>platform</code> 时：使用平台的 C++ 标准库替代 libc++（MSVC 目标平台使用微软的 STL，macOS 目标平台使用同一 SDK 中的 libc++），并改用 <code>&lt;target&gt;-system.cfg</code> 配置文件（<a href="./../guide/cross-compiling#the-platform-s-c-library">系统的 C++ 标准库</a>）。<code>@xclang//bazel:std</code> 会随之切换。其余目标平台以及 <code>--@xclang//runtimes:source</code> 均会拒绝这一选项</td></tr></tbody></table><h2 id="从源码构建运行时库" tabindex="-1">从源码构建运行时库 <a class="header-anchor" href="#从源码构建运行时库" aria-label="Permalink to &quot;从源码构建运行时库&quot;">​</a></h2><p>位于 <code>@xclang//runtimes</code> 下、作用于整个构建的参数（<a href="./../features/runtimes-from-source">从源码构建运行时库</a>）：</p><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th><th></th></tr></thead><tbody><tr><td><code>--@xclang//runtimes:source</code></td><td><code>false</code></td><td>使用工具链的 <code>libc++/src</code> 配合当前构建的特性与 <code>--copt</code> 为目标平台编译 libc++（含 libc++abi）、libc++experimental 与 libunwind，并在所有编译和链接中用它们替代预编译版本。在 MSVC 目标平台上会被拒绝</td></tr><tr><td><code>--@xclang//runtimes:hardening</code></td><td><code>none</code></td><td>libc++ 的加固模式：<code>none</code>、<code>fast</code>、<code>extensive</code>、<code>debug</code></td></tr><tr><td><code>--@xclang//runtimes:abi_version</code></td><td><code>1</code></td><td>libc++ 的 ABI 版本，<code>1</code> 或 <code>2</code></td></tr><tr><td><code>--@xclang//runtimes:abi_namespace</code></td><td><code>__&lt;version&gt;</code></td><td>libc++ 的内联 ABI 命名空间，格式为 <code>__&lt;name&gt;</code></td></tr><tr><td><code>--@xclang//runtimes:abi_defines</code></td><td>无</td><td>libc++ 的 ABI 宏（<code>_LIBCPP_ABI_*</code>），以逗号分隔</td></tr><tr><td><code>--@xclang//runtimes:exceptions</code></td><td><code>true</code></td><td>设为 <code>false</code> 时：构建禁用异常的 libc++ 与 libc++abi</td></tr><tr><td><code>--@xclang//runtimes:rtti</code></td><td><code>true</code></td><td>设为 <code>false</code> 时：构建禁用 RTTI 的 libc++；需同时设置 <code>exceptions=false</code></td></tr></tbody></table><p>这些运行时库是主机工具链仓库内的库目标，在与主构建相同但设置了 <code>@xclang//runtimes:building</code> 的独立配置下（使用不挂载源码运行时库的同一工具链），按 LLVM CMake 构建的方式编译（<code>bazel/runtimes_sources.bzl</code>）。构建启用的 sanitizer 特性会对 libc++ 与 libc++abi 插桩，但不会对 libunwind 或 MemorySanitizer 自身的运行时库插桩。所有运行时库均不启用 ThinLTO 编译。</p><p>遇到不支持的组合时，模块会立即停止构建并说明原因：在 MSVC 目标平台上启用从源码构建运行时库或设置任何相关参数；在未开启 <code>--@xclang//runtimes:source</code> 的情况下设置其他运行时库参数；在未开启源码运行时库或非 glibc 目标平台上启用 <code>msan</code>；或者启用了目标平台没有对应运行时库的 sanitizer 特性。</p><h2 id="目标与规则" tabindex="-1">目标与规则 <a class="header-anchor" href="#目标与规则" aria-label="Permalink to &quot;目标与规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Label</th><th></th></tr></thead><tbody><tr><td><code>@xclang//bazel:std</code></td><td>针对当前目标平台的 libc++ <code>std</code> 与 <code>std.compat</code> 模块库目标，供其他目标依赖，使用当前构建的 <code>--cxxopt</code> 编译。配合 <code>--@xclang//bazel:stdlib=platform</code> 时，在 MSVC 目标平台上编译微软 STL 的模块，在 macOS 目标平台上则不可用（标记为不兼容）</td></tr><tr><td><code>@xclang//bazel:debug_symbols.bzl</code> 中的 <code>xclang_debug_symbols(name, binary, gsymutil_args)</code></td><td>在除 MSVC 以外的所有目标平台上，调用单线程的 llvm-gsymutil 生成 <code>&lt;binary&gt;.gsym</code>（每次运行产出相同文件，<code>gsymutil_args</code> 追加在 <code>--num-threads=1</code> 之后），并在 macOS 目标平台上同时输出 <code>&lt;binary&gt;.dSYM</code>（需在 <code>cc_binary</code> 上启用 <code>generate_dsym_file</code>）；llvm-gsymutil 的日志位于输出组 <code>gsym_log</code> 中。在 MSVC 目标平台上则输出 <code>&lt;binary&gt;.pdb</code>（配合 <code>generate_pdb_file</code>）</td></tr><tr><td><code>@xclang//bazel:llvm-gsymutil</code></td><td>当前主机工具链中的 llvm-gsymutil，可通过 <code>bazel run</code> 直接运行：<code>bazel run @xclang//bazel:llvm-gsymutil -- &lt;absolute .gsym&gt; --address=0x&lt;address&gt;</code></td></tr><tr><td><code>@xclang//bazel:resource_dir.bzl</code> 中的 <code>xclang_resource_dir(name, srcs)</code></td><td>将 clang 的资源目录按 <code>lib/clang/&lt;major&gt;/</code> 布置在调用它的包内，供同一包内的 <code>bin/&lt;name&gt;</code> 可执行文件使用；默认取自 <code>@libclang</code></td></tr></tbody></table><h2 id="标签" tabindex="-1">标签 <a class="header-anchor" href="#标签" aria-label="Permalink to &quot;标签&quot;">​</a></h2><p>属于模块扩展 <code>use_extension(&quot;@xclang//bazel:extensions.bzl&quot;, &quot;xclang&quot;)</code> 的标签，仅在根模块中生效：用于在接受厂商许可证的前提下从厂商获取 SDK（<a href="./../integrations/bazel#build-for-msvc-and-for-macos-anywhere">构建 MSVC 目标平台，以及在任意主机上构建 macOS</a>）。各选项与 <code>xclang sdk fetch</code> 一致（<a href="./../reference/xclang-command#versions">版本</a>）。</p><table tabindex="0"><thead><tr><th>标签</th><th></th></tr></thead><tbody><tr><td><code>xclang.windows_sdk(accept_license, preset, msvc_version, sdk_version)</code></td><td>面向 MSVC 目标平台获取微软的 CRT、STL 与 Windows SDK；设置 <code>accept_license = True</code> 表示接受 Visual Studio Build Tools 与 Windows SDK 许可条款</td></tr><tr><td><code>xclang.macos_sdk(accept_license, preset, version)</code></td><td>在非 macOS 主机上面向 macOS 目标平台获取 Apple 的 macOS SDK；设置 <code>accept_license = True</code> 表示接受 Xcode 与 Apple SDK 协议。<code>version = &quot;latest&quot;</code> 会选取拉取仓库当下 Apple 更新目录中列出的最新 SDK，不具备可复现性</td></tr></tbody></table><h2 id="仓库" tabindex="-1">仓库 <a class="header-anchor" href="#仓库" aria-label="Permalink to &quot;仓库&quot;">​</a></h2><p>由模块扩展 <code>use_extension(&quot;@xclang//bazel:extensions.bzl&quot;, &quot;xclang&quot;)</code> 提供；每个仓库仅在构建实际用到时才会按需拉取。</p><table tabindex="0"><thead><tr><th>仓库</th><th></th></tr></thead><tbody><tr><td><code>@libclang</code></td><td>当前目标平台的 libclang：包含带完整链接接口的 <code>@libclang//:clangBasic</code>、<code>:LLVMSupport</code> 等库目标，以及 <code>:headers</code>、<code>:resource_dir</code>、<code>:AllTargetsInfos</code>、<code>:AllTargetsDescs</code>、<code>:AllTargetsAsmParsers</code> 与 <code>:AllTargetsDisassemblers</code>。启用 <code>--features=asan</code> 时自动切换为 ASan 构建版本。不提供 MSVC 目标平台版本，依赖它的目标会自动标记为与 MSVC 目标平台不兼容</td></tr><tr><td><code>@libclang_asan</code></td><td>ASan 构建版本（面向 Linux x64 与 macOS arm64 目标平台）</td></tr><tr><td><code>@libclang_&lt;target&gt;</code></td><td>指定目标平台的 libclang</td></tr><tr><td><code>@llvm_option_inc</code></td><td>clang、lld、llvm-lib 与 llvm-dlltool 的选项表，作为纯头文件库提供</td></tr></tbody></table><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><p>通过 <code>--repo_env=&lt;name&gt;=&lt;value&gt;</code> 传入：</p><table tabindex="0"><thead><tr><th>变量</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_THINLTO_CACHE</code></td><td>链接器 ThinLTO 缓存目录的绝对路径；模块会自动创建这个目录（<a href="./../features/libclang#the-thinlto-cache">ThinLTO 缓存</a>）</td></tr><tr><td><code>XCLANG_ROOT</code></td><td>直接使用本机已解压的主机工具链，替代发布版本中的压缩包</td></tr><tr><td><code>XCLANG_LIBCLANG_ROOT</code>, <code>XCLANG_LIBCLANG_ASAN_ROOT</code></td><td>直接使用本机已解压的主机 libclang 或其 ASan 构建版本，替代发布版本中的压缩包</td></tr><tr><td><code>BAZEL_DO_NOT_DETECT_CPP_TOOLCHAIN=1</code></td><td>rules_cc 的变量：关闭其本机编译器探测。除非 <code>xclang</code> 的 <code>bazel_dep</code> 排在 <code>rules_cc</code> 之前，否则必须设置：Bazel 按模块 <code>bazel_dep</code> 的顺序匹配工具链，而 rules_cc 探测到的本机编译器会抢先接管主机构建（在 Windows 上还会接管所有 Windows 平台的构建）</td></tr><tr><td><code>BAZEL_NO_APPLE_CPP_TOOLCHAIN=1</code></td><td>apple_support 的变量：关闭其基于 Xcode clang 的工具链；在 Mac 上，如果 <code>apple_support</code> 的 <code>bazel_dep</code> 排在 <code>xclang</code> 之前，它会抢先接管 macOS 目标平台的构建</td></tr></tbody></table><h2 id="版本记录" tabindex="-1">版本记录 <a class="header-anchor" href="#版本记录" aria-label="Permalink to &quot;版本记录&quot;">​</a></h2><p><code>packages/bazel/bazel/versions.bzl</code> 记录了模块所下载的发布版本号，以及取自对应版本 <code>SHA256SUMS</code> 的各个压缩包 sha256 摘要。模块自身的版本号与发布版本号一致。</p>',34)])])}const g=d(a,[["render",l]]);export{m as __pageData,g as default};
